const D = { energy: .6, density: .55, scale: 1, speed: 1, noise: .4, trails: .6, hue: 200, x: .5, y: .5, style: 'plate', act: 'link', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const md = (a, n) => ((a % n) + n) % n;
// integer hash — finalize with >>> (>> sign-extends and caps the hash at 0.5)
function h2(ix, iy) { let h = (ix * 374761393 + iy * 668265263 + (P.seed | 0) * 1442695041) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967295; }
// Box-Muller from the integer hash: real Gaussian AWGN, not a uniform blob
function gauss(i, j) { const a = Math.max(h2(i, j), 1e-6), b = h2(i + 7919, j + 104729); return Math.sqrt(-2 * Math.log(a)) * Math.cos(TAU * b); }

const en = clp(P.energy, 0, 1), dens = clp(P.density, 0, 1), nz = clp(P.noise, 0, 1);
const W = width, H = height, u = Math.min(W, H);
const hs = P.hue - 200;

const ST = {
  // TONED report stock, not white — a near-white plate lands the frame ~0.6 and reads blank
  plate:  { pap:[42,24,48], grid:[8,58,44], ink:[210,44,22], sym:[206,58,26], hot:[16,74,52], lbl:[34,32,14], glow:0 },
  scope:  { pap:[210,42,10], grid:[190,44,30], ink:[168,66,88], sym:[164,72,94], hot:[46,86,99], lbl:[180,20,72], glow:1 },
  bench:  { pap:[228,34,8], grid:[224,30,26], ink:[38,88,92], sym:[40,90,97], hot:[6,84,96], lbl:[40,22,70], glow:.8 },
  ashen:  { pap:[220,6,16], grid:[220,5,32], ink:[0,0,92], sym:[0,0,98], hot:[0,0,100], lbl:[220,5,66], glow:0 }
};
const st = ST[P.style] || ST.plate;
const PAH = md(st.pap[0] + hs, 360), GRH = md(st.grid[0] + hs, 360), INH = md(st.ink[0] + hs, 360), SYH = md(st.sym[0] + hs, 360), HOH = md(st.hot[0] + hs, 360), LBH = md(st.lbl[0] + hs, 360);

// ---- act dramaturgy: the link's health over minutes ----
const ORD = dens < .33 ? 4 : dens < .66 ? 6 : 8;         // 16 / 36 / 64-QAM
const M = ORD * ORD;
let snr, phn, iqI, comp;
if (P.act === 'fading') {
  const f = 0.5 + 0.5 * Math.sin(K.t * 0.047) * Math.sin(K.t * 0.111 + 1.3);
  snr = 9 + f * 22; phn = 0.10 - f * 0.075; iqI = 0.05; comp = 0.16 * (1 - f);
} else if (P.act === 'degrade') {
  const f = md(K.t * 0.0085, 1);                         // a slow slide into the noise, then a reset
  snr = 34 - f * 26; phn = 0.012 + f * 0.10; iqI = f * 0.14; comp = f * 0.24;
} else {
  snr = 20 + 9 * Math.sin(K.t * 0.031) + 4 * Math.sin(K.t * 0.083); phn = 0.022; iqI = 0.018; comp = 0.05;
}
snr = clp(snr - nz * 14, 3, 40);
phn = clp(phn + nz * 0.05, 0, 0.4);
const sigN = Math.pow(10, -snr / 20) * 1.35;             // noise sigma from SNR in dB

const cx = P.x * W, cy = P.y * H, R = 0.40 * u * clp(P.scale, .3, 2.2);
const lev = i => (2 * i - (ORD - 1)) / (ORD - 1);        // ideal symbol levels, normalised to +-1
const EXT = 1.35;                                        // IQ half-extent held in the buffer

// ---- carrier offset: irrational period (~13.7 s) -> never re-phases at the 8 s gate ----
const rot = K.t * (TAU / 13.7) * clp(0.3 + P.speed * .7, 0, 3) + 0.24 * Math.sin(K.t * 0.083);

// channel impairments live in IQ space (pre-rotation) so persistence accumulates as
// tight clouds instead of being smeared into arcs by the carrier offset
function chan(i, q) {
  let a = i * (1 + iqI), b = q * (1 - iqI) + i * iqI * 0.55;
  const m = Math.hypot(a, b);
  if (m > 1e-6) { const g = 1 - comp * m * m; a *= g; b *= g; }
  return [a, b];
}
const NB = 320, bs = NB / (2 * EXT);
const BX = (i) => (i + EXT) * bs, BY = (q) => (EXT - q) * bs;

// ---- persistence buffer, in the receiver's own (unrotated) frame ----
if (!S.pers || S.pk !== NB) { if (S.pers && S.pers.remove) S.pers.remove(); S.pers = createGraphics(NB, NB); S.pers.pixelDensity(1); S.pers.colorMode(S.pers.HSB, 360, 100, 100, 100); S.pk = NB; }
const pg = S.pers;
let dt = K.t - (S.lastT == null ? K.t - 1 / 60 : S.lastT);
if (dt < 0 || dt > 0.25) dt = 1 / 60;                    // tolerate t0 reset
S.lastT = K.t;

// soft exponential decay to transparent — slow persistence, never a flicker
const pdc = pg.drawingContext;
pdc.globalCompositeOperation = 'destination-out';
pg.noStroke(); pg.fill(0, 0, 0, Math.max(1.6, 100 * (1 - Math.exp(-dt / 0.62))));
pg.rect(0, 0, NB, NB);
pdc.globalCompositeOperation = 'source-over';

// ---- splat this frame's symbols: ~200/frame accumulating into ~6k over the persistence ----
const SPS = clp(Math.round(M * (1.6 + en * 2.4)), 40, 260);
const tick = Math.floor(K.t * 240);
const dotR = Math.max(1.5, NB * .011 * (0.6 + en * .6));
if (st.glow) pdc.globalCompositeOperation = 'lighter';
pg.noStroke();
for (let n = 0; n < SPS; n++) {
  const s = (tick * 977 + n * 31) | 0;
  const si = Math.floor(h2(s, 13) * ORD), sq = Math.floor(h2(s, 17) * ORD);
  let i = lev(si), q = lev(sq);
  i += gauss(s, 23) * sigN; q += gauss(s, 29) * sigN;                       // AWGN
  const th = Math.atan2(q, i) + gauss(s, 31) * phn, mg = Math.hypot(i, q); // phase noise smears tangentially
  i = Math.cos(th) * mg; q = Math.sin(th) * mg;
  const c = chan(i, q);
  const err = Math.hypot(i - lev(si), q - lev(sq));
  const hot = clp(err / 0.36, 0, 1);                                        // colour by error vector magnitude
  pg.fill(hot > .55 ? HOH : SYH, st.sym[1] * (0.5 + 0.5 * hot), st.sym[2] * (0.55 + 0.45 * hot), st.glow ? 40 : 74);
  pg.ellipse(BX(c[0]), BY(c[1]), dotR);
}

// ---- transition trajectories: pulse-shaped paths, fading in the same phosphor ----
const tA = clp(P.trails, 0, 1);
if (tA > 0.02) {
  const NT = clp(Math.round(tA * 7), 0, 8);
  pg.noFill(); pg.stroke(INH, st.ink[1] * .8, st.ink[2], (st.glow ? 22 : 40) * tA); pg.strokeWeight(1.2);
  for (let n = 0; n < NT; n++) {
    const s = (tick * 131 + n * 7717) | 0;
    const a = [lev(Math.floor(h2(s, 41) * ORD)), lev(Math.floor(h2(s, 43) * ORD))];
    const b = [lev(Math.floor(h2(s + 1, 41) * ORD)), lev(Math.floor(h2(s + 1, 43) * ORD))];
    pg.beginShape();
    for (let k = 0; k <= 12; k++) {
      const tt = k / 12;
      // raised-cosine overshoot: the trajectory bows past the target and rings back
      const w = tt - Math.sin(TAU * tt) * 0.16, ov = Math.sin(Math.PI * tt) * 0.20;
      const c = chan(a[0] + (b[0] - a[0]) * w + ov * (b[1] - a[1]) * .35,
                     a[1] + (b[1] - a[1]) * w - ov * (b[0] - a[0]) * .35);
      pg.vertex(BX(c[0]), BY(c[1]));
    }
    pg.endShape();
  }
}
pdc.globalCompositeOperation = 'source-over';

// =================== composite ===================
const dc = drawingContext;
noStroke();
background(PAH, st.pap[1], st.pap[2]);
// toned stock: fine grain so the ground is never a flat fill
const gkey = P.style + '|' + Math.round(P.hue) + '|' + (P.seed | 0);
if (!S.tone || S.gkey !== gkey) {
  if (S.tone && S.tone.remove) S.tone.remove();
  const g = createGraphics(256, 256); g.pixelDensity(1); g.colorMode(g.HSB, 360, 100, 100, 100);
  g.clear(); g.noStroke();
  for (let i = 0; i < 5200; i++) {
    g.fill(PAH, st.pap[1] * (0.6 + h2(i, 3)), st.pap[2] * (h2(i, 5) > .5 ? 1.5 : .55), 9);
    g.rect(h2(i, 7) * 256, h2(i, 11) * 256, 1.4, 1.4);
  }
  S.tone = g; S.gkey = gkey;
}
for (let ty = 0; ty < Math.ceil(H / 256); ty++) for (let tx = 0; tx < Math.ceil(W / 256); tx++) image(S.tone, tx * 256, ty * 256, 256, 256);

push();
translate(cx, cy);
rotate(rot);                        // the receiver's frame turns under the uncorrected carrier
// decision grid
dc.beginPath();
for (let i = 0; i < ORD - 1; i++) {
  const b = (lev(i) + lev(i + 1)) * .5 * (1 + iqI) * R;
  dc.moveTo(b, -R * 1.28); dc.lineTo(b, R * 1.28);
  dc.moveTo(-R * 1.28, b); dc.lineTo(R * 1.28, b);
}
dc.lineWidth = Math.max(1, u * .0011);
dc.strokeStyle = color(GRH, st.grid[1], st.grid[2], 40).toString();
dc.stroke();
// I / Q axes
stroke(GRH, st.grid[1], st.grid[2] * 1.5, 72); strokeWeight(Math.max(1.4, u * .0017));
line(-R * 1.30, 0, R * 1.30, 0); line(0, -R * 1.30, 0, R * 1.30);
// the phosphor
blendMode(BLEND);
image(pg, -R * EXT, -R * EXT, R * EXT * 2, R * EXT * 2);
// ideal constellation targets
stroke(INH, st.ink[1], st.ink[2], 76); strokeWeight(Math.max(1, u * .0013));
const xr = Math.max(2.5, R * .016);
for (let a = 0; a < ORD; a++) for (let b = 0; b < ORD; b++) {
  const c = chan(lev(a), lev(b));
  line(c[0] * R - xr, c[1] * -R, c[0] * R + xr, c[1] * -R);
  line(c[0] * R, c[1] * -R - xr, c[0] * R, c[1] * -R + xr);
}
noStroke(); fill(LBH, st.lbl[1], st.lbl[2] * .8, 62);
textFont('Courier New'); textSize(clp(u * .0115, 6, 20));
textAlign(CENTER, CENTER); text('I', R * 1.16, 0); text('Q', 0, -R * 1.16);
pop();

// dB rings (fixed in the analyser's frame, not the carrier's)
noFill();
for (let k = 1; k <= 3; k++) { stroke(GRH, st.grid[1], st.grid[2], 26); strokeWeight(1); ellipse(cx, cy, R * 2 * k / 3 * 1.02); }

// ---- readouts: the instrument's voice ----
const evm = clp(sigN * 100 * 1.6 + phn * 42, 0, 99);
textFont('Courier New'); noStroke();
textAlign(LEFT, TOP); textSize(clp(u * .017, 8, 30));
fill(LBH, st.lbl[1], st.lbl[2], 90);
text('CONSTELLATION  ·  ' + M + '-QAM', u * .032, u * .028);
textSize(clp(u * .0115, 6, 20)); fill(LBH, st.lbl[1], st.lbl[2] * .84, 72);
const rows = [
  'MER      ' + snr.toFixed(1) + ' dB',
  'EVM      ' + evm.toFixed(2) + ' %',
  'PH NOISE ' + (phn * 1000).toFixed(1) + ' mrad',
  'IQ IMB   ' + (iqI * 100).toFixed(2) + ' %',
  'CFO      ' + (clp(0.3 + P.speed * .7, 0, 3) * 73).toFixed(1) + ' Hz',
  'SYM RATE 6.875 MBd'
];
for (let i = 0; i < rows.length; i++) text(rows[i], u * .032, u * .055 + i * u * .020);
textAlign(RIGHT, TOP); fill(LBH, st.lbl[1], st.lbl[2] * .84, 72);
text(P.act.toUpperCase(), W - u * .032, u * .028);
const lock = evm < 22;
fill(lock ? md(150 + hs, 360) : md(8 + hs, 360), 62, lock ? 84 : 92, 60 + 26 * K.swell);
text(lock ? 'LOCKED' : 'UNLOCKED', W - u * .032, u * .050);

// ---- soft persistence bloom: broad, slow, no flicker ----
if (st.glow) {
  blendMode(ADD); noStroke();
  const br = 0.55 + 0.45 * Math.sin(K.t * 0.059 + 0.7);
  for (let k = 0; k < 3; k++) { fill(SYH, st.sym[1] * .5, 100, 2.2 * st.glow * (0.6 + br * .5)); ellipse(cx, cy, R * (1.4 + k * .5), R * (1.4 + k * .5)); }
  blendMode(BLEND);
}
noFill(); stroke(0, 0, 0, 24); strokeWeight(u * .10); rect(-u * .05, -u * .05, W + u * .1, H + u * .1);
dc.shadowBlur = 0;
blendMode(BLEND);
if (P.alpha < 100) { noStroke(); fill(PAH, st.pap[1], st.pap[2], 100 - clp(P.alpha, 0, 100)); rect(0, 0, W, H); }
